          gap: 0.5rem;
        }

        .mood-section-title {
          font-size: 1.5rem;
          font-weight: 600;
          color: #333;
        }

        .mood-insights-grid {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
          gap: 1.5rem;
          margin-bottom: 2rem;
        }

        .mood-insight-card {
          background: rgba(255, 255, 255, 0.8);
          backdrop-filter: blur(10px);
          border-radius: 12px;
          padding: 1.5rem;
          box-shadow: 0 8px 32px rgba(0, 0, 0, 0.06);
          border: 1px solid rgba(255, 255, 255, 0.8);
          min-height: 200px;
          display: flex;
          flex-direction: column;
          gap: 1rem;
          cursor: pointer;
          transition: all 0.3s ease;
          position: relative;
          overflow: hidden;
        }

        .mood-insight-card:hover {
          transform: translateY(-5px);
          box-shadow: 0 12px 32px rgba(0, 0, 0, 0.1);
        }

        .mood-insight-icon {
          width: 50px;
          height: 50px;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          background: ${moodGradients.main};
          color: white;
          font-size: 1.5rem;
          margin-bottom: 0.5rem;
        }

        .mood-insight-title {
          font-size: 1.2rem;
          font-weight: 600;
          color: #333;
          margin-bottom: 0.5rem;
        }

        .mood-insight-text {
          font-size: 1rem;
          color: #666;
          line-height: 1.6;
        }

        .insight-content {
          position: relative;
          height: 150px;
          overflow: hidden;
        }

        .insight-content-gradient {
          position: absolute;
          bottom: 0;
          left: 0;
          right: 0;
          height: 50px;
          background: linear-gradient(to bottom, transparent, rgba(255,255,255,0.9));
          pointer-events: none;
        }

        .insight-card-expand-hint {
          text-align: center;
          margin-top: 0.5rem;
          color: #43C6AC;
          font-weight: 500;
          font-size: 14px;
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 4px;
          transition: all 0.3s ease;
          transform: translateY(5px);
          opacity: 0.7;
        }

        .mood-insight-card:hover .insight-card-expand-hint {
          transform: translateY(0);
          opacity: 1;
        }

        /* Modal stili */
        .insight-modal {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: rgba(0, 0, 0, 0.5);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 1000;
          padding: 1rem;
          animation: modalBounce 0.5s ease-out;
        }

        .modal-content {
          background: white;
          border-radius: 12px;
          max-width: 600px;
          width: 100%;
          max-height: 80vh;
          overflow-y: auto;
          padding: 2rem;
          position: relative;
          box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
        }

        .modal-close {
          position: absolute;
          top: 1rem;
          right: 1rem;
          background: none;
          border: none;
          font-size: 1.5rem;
          cursor: pointer;
          color: #aaa;
          transition: color 0.3s;
        }

        .modal-close:hover {
          color: #333;
        }

        .modal-header {
          display: flex;
          align-items: center;
          gap: 1rem;
          margin-bottom: 1.5rem;
          border-bottom: 1px solid #eee;
          padding-bottom: 1rem;
        }

        .modal-icon {
          width: 40px;
          height: 40px;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          background: ${moodGradients.main};
          color: white;
          font-size: 1.2rem;
        }

        .modal-title {
          font-size: 1.5rem;
          font-weight: 600;
          color: #333;
        }

        .modal-body {
          font-size: 1rem;
          color: #666;
          line-height: 1.8;
        }

        .modal-body p {
          margin-bottom: 1rem;
        }

        @keyframes modalBounce {
          0% { transform: scale(0.8); opacity: 0; }
          50% { transform: scale(1.05); opacity: 1; }
          100% { transform: scale(1); opacity: 1; }
        }
